def solve(payload):
    capacity = payload.get('capacity', 0)
    rows = sorted(payload.get('requests', []), key=lambda row: (-row.get('benefit', 0), row.get('id', '')))
    selected = []
    used = 0
    benefit = 0
    for row in rows:
        if used + row.get('units', 0) <= capacity:
            selected.append(row.get('id'))
            used += row.get('units', 0)
            benefit += row.get('benefit', 0)
    return {'selected': sorted(selected), 'used': used, 'benefit': benefit}

